#include <iostream>
#include <optional>
#include <vector>

class QueueFromStacks {
    std::vector<int> incoming_;
    std::vector<int> outgoing_;

    void prepare_front() {
        if (!outgoing_.empty() || incoming_.empty()) return;
        outgoing_.reserve(incoming_.size());
        while (!incoming_.empty()) {
            outgoing_.push_back(incoming_.back());
            incoming_.pop_back();
        }
    }

public:
    QueueFromStacks() = default;
    QueueFromStacks(const QueueFromStacks&) = delete;
    QueueFromStacks& operator=(const QueueFromStacks&) = delete;
    QueueFromStacks(QueueFromStacks&&) = delete;
    QueueFromStacks& operator=(QueueFromStacks&&) = delete;

    void enqueue(int value) { incoming_.push_back(value); }

    std::optional<int> front() {
        prepare_front();
        if (outgoing_.empty()) return std::nullopt;
        return outgoing_.back();
    }

    std::optional<int> dequeue() {
        prepare_front();
        if (outgoing_.empty()) return std::nullopt;
        const int value = outgoing_.back();
        outgoing_.pop_back();
        return value;
    }

    bool empty() const noexcept {
        return incoming_.empty() && outgoing_.empty();
    }
};

void report(const char* label, std::optional<int> value) {
    std::cout << label << ": ";
    if (value) std::cout << *value;
    else std::cout << "empty";
    std::cout << '\n';
}

int main() {
    QueueFromStacks queue;
    report("empty front", queue.front());
    queue.enqueue(41);
    queue.enqueue(17);
    queue.enqueue(41);
    report("first front", queue.front());
    report("repeat front", queue.front());
    report("dequeue", queue.dequeue());
    queue.enqueue(26);
    queue.enqueue(8);
    report("front after arrivals", queue.front());
    for (int attempt = 0; attempt < 5; ++attempt)
        report("dequeue", queue.dequeue());
    queue.enqueue(-5);
    report("reuse", queue.dequeue());
    std::cout << "finally empty: " << std::boolalpha << queue.empty() << '\n';
}
